// Remember-me tokens. Keyed by sha256 of the token, so the raw token exists
// only in the caller's cookie — a dump of this map cannot be replayed.
const rememberTokens = new Map();

const REMEMBER_TOKEN_TTL_MS = 30 * 24 * 60 * 60 * 1000;

function hashToken(token) {
  return crypto.createHash('sha256').update(token).digest('hex');
}

// 32 random bytes, base64url-encoded: url-safe and cookie-safe as-is.
function generateRememberToken(userId) {
  const token = 'rmb-' + crypto.randomBytes(32).toString('base64url');
  const now = Date.now();
  rememberTokens.set(hashToken(token), {
    userId,
    createdAt: now,
    expiresAt: now + REMEMBER_TOKEN_TTL_MS,
  });
  return token;
}

function validateRememberToken(token) {
  if (typeof token !== 'string' || token.length === 0) return null;
  const key = hashToken(token);
  const record = rememberTokens.get(key);
  if (!record) return null;
  if (record.expiresAt <= Date.now()) {
    rememberTokens.delete(key);
    return null;
  }
  return { userId: record.userId };
}

function revokeRememberToken(token) {
  if (typeof token !== 'string') return false;
  return rememberTokens.delete(hashToken(token));
}

module.exports = {
  login,
  getSession,
  generateSessionId,
  generateRememberToken,
  validateRememberToken,
  revokeRememberToken,
};

