test('wrong password is rejected', () => {
  const res = login('alice', 'nope');
  assert.strictEqual(res.ok, false);
  assert.strictEqual(res.sessionId, undefined);
});

test('remember token round-trips to its user', () => {
  const token = generateRememberToken('u1');
  assert.deepStrictEqual(validateRememberToken(token), { userId: 'u1' });
});

test('remember token is url-safe', () => {
  const token = generateRememberToken('u1');
  assert.match(token, /^[A-Za-z0-9\-._~]+$/);
  assert.strictEqual(encodeURIComponent(token), token);
});

test('remember tokens are unique and unguessable in length', () => {
  const tokens = new Set();
  for (let i = 0; i < 100; i++) tokens.add(generateRememberToken('u1'));
  assert.strictEqual(tokens.size, 100);
  // 32 random bytes, base64url-encoded, after the 'rmb-' prefix
  for (const token of tokens) assert.ok(token.length - 4 >= 43);
});

test('unknown, empty and non-string tokens are rejected', () => {
  assert.strictEqual(validateRememberToken('rmb-nope'), null);
  assert.strictEqual(validateRememberToken(''), null);
  assert.strictEqual(validateRememberToken(null), null);
  assert.strictEqual(validateRememberToken(undefined), null);
  assert.strictEqual(validateRememberToken(42), null);
  assert.strictEqual(validateRememberToken({}), null);
});

test('the raw token is not what is stored server-side', () => {
  const token = generateRememberToken('u1');
  const stored = JSON.stringify([...require('../src/auth.js').__rememberStore()]);
  assert.ok(!stored.includes(token), 'raw token must not be stored at rest');
  assert.ok(stored.includes('u1'));
});

